INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(550, 'ballet', '/bæˈleɪ/', 'noun', '{"zh-TW":["芭蕾舞"],"en":["a form of artistic dancing"]}', NULL, 'ballet dancer / ballet class', '[{"en":"She has studied ballet since age five.","zh-TW":"她從五歲開始學芭蕾。"},{"en":"We saw a beautiful ballet performance.","zh-TW":"我們看了一場美麗的芭蕾表演。"}]', NULL, NULL, 2, 550, NULL),
(551, 'ballot', '/ˈbælət/', 'noun', '{"zh-TW":["選票；投票"],"en":["a piece of paper used to vote"]}', NULL, 'secret ballot / ballot box', '[{"en":"Voters cast their ballots.","zh-TW":"選民投下了他們的選票。"},{"en":"The election was decided by ballot.","zh-TW":"選舉以投票方式決定。"}]', NULL, NULL, 2, 551, NULL),
(552, 'ban', '/bæn/', 'verb', '{"zh-TW":["禁止；禁令"],"en":["to officially prohibit something"]}', '{"root":{"text":"ban","meaning":"proclaim/forbid (宣告/禁止)"},"logic":"宣告禁止，即「禁止」。"}', 'ban on / impose a ban', '[{"en":"The city imposed a ban on single-use plastics.","zh-TW":"該市對一次性塑膠實施禁令。"},{"en":"Smoking is banned in all public buildings.","zh-TW":"所有公共建築內禁止吸菸。"}]', NULL, NULL, 1, 552, NULL),
(553, 'band', '/bænd/', 'noun', '{"zh-TW":["樂隊；帶子"],"en":["a group of musicians"]}', NULL, 'rock band / rubber band', '[{"en":"He plays guitar in a band.","zh-TW":"他在樂隊裡彈吉他。"},{"en":"The band performed live on stage.","zh-TW":"樂隊在舞台上現場演出。"}]', NULL, NULL, 1, 553, NULL),
(554, 'bandwidth', '/ˈbændwɪdθ/', 'noun', '{"zh-TW":["頻寬"],"en":["the amount of data that can be transmitted"]}', NULL, 'high bandwidth / bandwidth limit', '[{"en":"We need more bandwidth for video calls.","zh-TW":"我們需要更多頻寬進行視訊通話。"},{"en":"The server has limited bandwidth.","zh-TW":"伺服器頻寬有限。"}]', NULL, NULL, 3, 554, 752),
(555, 'bandwidth throttling', '/ˈbændwɪdθ ˈθrɒtəlɪŋ/', 'noun', '{"zh-TW":["頻寬限制"],"en":["intentional slowing of internet speed by a service provider"]}', NULL, 'apply bandwidth throttling / bandwidth throttling policy / avoid bandwidth throttling', '[{"en":"ISPs use bandwidth throttling to manage network congestion.","zh-TW":"網路服務提供商使用頻寬限制來管理網路擁塞。"},{"en":"The streaming service experienced bandwidth throttling during peak hours.","zh-TW":"串流服務在高峰時段遭遇頻寬限制。"}]', '{"verb":"throttle","noun":"throttle"}', NULL, 5, 555, NULL),
(556, 'bank', '/bæŋk/', 'noun', '{"zh-TW":["【主要意義-名詞】銀行；河岸","【次要意義-動詞】依靠；指望（bank on）","【次要意義-動詞】（飛機/車）傾斜轉彎","【次要意義-名詞】一排；一組（電腦/設備）"],"en":["[primary - noun] a financial institution; the land beside a river","[secondary - verb] to rely or depend on someone or something","[secondary - verb] to tilt to one side when turning","[secondary - noun] a row or series of similar objects"]}', NULL, 'bank on / bank holiday / bank of screens / river bank', '[{"en":"We cannot bank on government subsidies to cover the shortfall.","zh-TW":"我們不能指望政府補貼來彌補缺口。"},{"en":"The control room features a bank of monitoring screens.","zh-TW":"控制室配備了一排監控螢幕。"},{"en":"The branch manager banked on strong customer loyalty to boost sales.","zh-TW":"分行經理指望強烈的客戶忠誠度來提升銷售額。"}]', '{"noun":"banking, banker"}', 'bank on = 「依靠/指望」是 TOEIC 商業文章常見片語，a bank of（一排……）描述設備群組，這些次要意義完全不同於「銀行」，是常見陷阱。', 1, 556, NULL),
(557, 'bank guarantee', '/bæŋk ˌɡærənˈtiː/', 'noun', '{"zh-TW":["銀行擔保"],"en":["a commitment by a bank to cover a borrower''s obligations if they default"]}', NULL, 'issue a bank guarantee / bank guarantee amount', '[{"en":"A bank guarantee was required before the construction contract was awarded.","zh-TW":"在授予建設合約前需要銀行擔保。"},{"en":"The bank guarantee protected the developer against contractor default.","zh-TW":"銀行擔保保護了開發商免受承包商違約的影響。"}]', NULL, NULL, 5, 557, NULL),
(558, 'bank reconciliation', '/bæŋk ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["銀行對帳；銀行核帳"],"en":["comparing internal accounting records with bank statements to find discrepancies"]}', NULL, 'perform bank reconciliation / monthly bank reconciliation', '[{"en":"Bank reconciliation is performed every month to verify accuracy.","zh-TW":"每月進行銀行對帳以核實準確性。"},{"en":"The bank reconciliation identified a double payment of 5000.","zh-TW":"銀行對帳識別了一筆5000元的雙重付款。"}]', NULL, NULL, 5, 558, NULL),
(559, 'bank statement', '/bæŋk ˈsteɪtmənt/', 'noun', '{"zh-TW":["銀行對帳單"],"en":["a document from a bank showing all transactions in an account"]}', NULL, 'review the bank statement / reconcile the bank statement', '[{"en":"The accountant reviewed the bank statement to find the discrepancy.","zh-TW":"會計師審查了銀行對帳單以找出差異。"},{"en":"Monthly bank statements are essential for accurate bookkeeping.","zh-TW":"每月銀行對帳單對準確記帳至關重要。"}]', NULL, NULL, 5, 559, NULL),
(560, 'bank transfer', '/bæŋk ˈtrænsfɜːr/', 'noun', '{"zh-TW":["銀行轉帳"],"en":["the movement of money between bank accounts"]}', NULL, 'initiate a bank transfer / bank transfer fee', '[{"en":"She initiated a bank transfer to pay the vendor.","zh-TW":"她發起了一筆銀行轉帳來支付供應商款項。"},{"en":"International bank transfers may take two to five business days.","zh-TW":"國際銀行轉帳可能需要兩到五個工作日。"}]', NULL, NULL, 5, 560, NULL),
(561, 'bankrupt', '/ˈbæŋkrʌpt/', 'adjective', '{"zh-TW":["破產的"],"en":["unable to pay debts"]}', NULL, 'go bankrupt / declare bankrupt', '[{"en":"The company went bankrupt.","zh-TW":"公司破產了。"},{"en":"He was declared bankrupt by the court.","zh-TW":"他被法院宣告破產。"}]', '{"noun":"bankruptcy"}', NULL, 3, 561, NULL),
(562, 'bankruptcy', '/ˈbæŋkrʌptsi/', 'noun', '{"zh-TW":["破產"],"en":["a legal process for individuals or companies unable to repay debts"]}', NULL, 'declare bankruptcy / file for bankruptcy / bankruptcy protection', '[{"en":"The retail chain declared bankruptcy after the pandemic.","zh-TW":"這家零售連鎖店在疫情後宣布破產。"},{"en":"Bankruptcy protection gave the company time to restructure.","zh-TW":"破產保護給了公司重組的時間。"}]', '{"adjective":"bankrupt","verb":"bankrupt"}', NULL, 4, 562, NULL),
(563, 'bankruptcy protection', '/ˈbæŋkrʌptsi prəˈtekʃən/', 'noun', '{"zh-TW":["破產保護"],"en":["legal protection granted to an insolvent debtor preventing creditors from collecting"]}', NULL, 'file for bankruptcy protection / granted bankruptcy protection', '[{"en":"The retailer filed for bankruptcy protection to restructure its debts.","zh-TW":"零售商申請破產保護以重組其債務。"},{"en":"Under bankruptcy protection, operations can continue while debts are reorganized.","zh-TW":"在破產保護下，可以在重組債務的同時繼續運營。"}]', '{"synonym":"Chapter 11 protection"}', NULL, 5, 563, NULL),
(564, 'banquet', '/ˈbæŋkwɪt/', 'noun', '{"zh-TW":["宴會；盛宴"],"en":["an elaborate meal for many people"]}', NULL, 'banquet hall / corporate banquet', '[{"en":"The hotel''s banquet hall can accommodate 500 guests.","zh-TW":"飯店的宴會廳可容納500位賓客。"},{"en":"They hosted a banquet to celebrate the company''s anniversary.","zh-TW":"他們舉辦了宴會慶祝公司周年紀念。"}]', '{"verb":"banquet"}', NULL, 3, 564, NULL),
(565, 'banquet hall', '/ˈbæŋkwɪt hɔːl/', 'noun', '{"zh-TW":["宴會廳"],"en":["a large hall used for formal dinners or events"]}', NULL, 'book a banquet hall / banquet hall capacity', '[{"en":"The banquet hall can accommodate up to 300 guests.","zh-TW":"宴會廳最多可容納300位賓客。"},{"en":"The annual gala will be held in the hotel''s banquet hall.","zh-TW":"年度晚會將在飯店的宴會廳舉行。"}]', NULL, NULL, 4, 565, NULL),
(566, 'bar', '/bɑːr/', 'noun', '{"zh-TW":["酒吧；條；障礙"],"en":["a place serving drinks; a long narrow piece"]}', NULL, 'behind bars / bar chart', '[{"en":"Let''s meet at the bar.","zh-TW":"我們在酒吧見面吧。"},{"en":"He was put behind bars.","zh-TW":"他被關進了監獄。"}]', '{"verb":"bar","noun2":"bartender"}', NULL, 1, 566, NULL),
(567, 'bar chart', '/bɑːr tʃɑːrt/', 'noun', '{"zh-TW":["長條圖；柱狀圖"],"en":["a chart using bars to show comparisons"]}', NULL, 'create a bar chart / bar chart analysis', '[{"en":"The bar chart clearly shows the revenue growth over five years.","zh-TW":"長條圖清楚地顯示了五年來的收入增長。"},{"en":"Use a bar chart to compare sales across regions.","zh-TW":"使用長條圖比較各地區的銷售情況。"}]', NULL, NULL, 3, 567, NULL),
(568, 'barely', '/ˈbeərli/', 'adverb', '{"zh-TW":["勉強；幾乎不"],"en":["only just; almost not"]}', '{"root":{"text":"bare","meaning":"bare/merely (僅僅)"},"suffix":{"text":"-ly","meaning":"in manner of (以…方式)"},"logic":"僅僅的方式，即「勉強」。"}', 'barely visible / barely enough / can barely', '[{"en":"She barely passed the exam.","zh-TW":"她勉強通過了考試。"},{"en":"I can barely hear you.","zh-TW":"我幾乎聽不到你說話。"}]', NULL, NULL, 2, 568, NULL),
(569, 'bargain', '/ˈbɑːrɡɪn/', 'noun', '{"zh-TW":["便宜貨；協議","討價還價","便宜貨；交易"],"en":["something bought cheaply","an agreement between parties","to negotiate terms of a deal"]}', '{"root":{"text":"bargain","meaning":"trade/negotiate (交易)"},"logic":"通過交易談判達成的，即「便宜貨、協議」。"}', 'bargain price / collective bargaining; a real bargain / bargain hunter', '[{"en":"The property was a real bargain at that price.","zh-TW":"以那個價格買下這處房產真是便宜。"},{"en":"The union engaged in collective bargaining.","zh-TW":"工會進行了集體談判。"},{"en":"This coat was a real bargain at half price.","zh-TW":"這件外套半價，真是便宜貨。"},{"en":"They bargained with the vendor for a lower price.","zh-TW":"他們跟攤販討價還價。"}]', '{"verb":"bargain"}', NULL, 3, 569, NULL),
(570, 'bargaining power', '/ˈbɑːrɡənɪŋ ˈpaʊər/', 'noun', '{"zh-TW":["議價能力"],"en":["the relative power of parties in a negotiation to influence the outcome"]}', NULL, 'increase bargaining power / strong bargaining power', '[{"en":"Large retailers have significant bargaining power over their suppliers.","zh-TW":"大型零售商對其供應商有顯著的議價能力。"},{"en":"Consolidating purchases improves a buyer''s bargaining power.","zh-TW":"整合採購提高了買家的議價能力。"}]', '{"verb":"bargain"}', NULL, 5, 570, NULL),
(571, 'barrier', '/ˈbæriər/', 'noun', '{"zh-TW":["障礙；壁壘","障礙；屏障"],"en":["a fence or obstacle that prevents movement or access","something that prevents movement or access"]}', '{"root":{"text":"bar","meaning":"bar/block (阻擋)"},"suffix":{"text":"-ier","meaning":"thing that (…的東西)"},"logic":"阻擋的東西，即「障礙」。"}', 'trade barrier / language barrier / barrier to entry; language barrier / trade barrier / break down barriers', '[{"en":"Language barriers can hinder international business.","zh-TW":"語言障礙可能妨礙國際商務。"},{"en":"The company faced significant barriers to entry.","zh-TW":"公司面臨重大的進入門檻。"},{"en":"Language can be a barrier to communication.","zh-TW":"語言可能是溝通的障礙。"},{"en":"They are trying to break down trade barriers.","zh-TW":"他們正試圖消除貿易障礙。"}]', NULL, NULL, 3, 571, 513),
(572, 'barrier to entry', '/ˈbæriər tə ˈentri/', 'noun', '{"zh-TW":["進入壁壘"],"en":["an obstacle that makes it difficult for new competitors to enter a market"]}', NULL, 'high barrier to entry / reduce barriers to entry / overcome barriers to entry', '[{"en":"Patents create a high barrier to entry in pharmaceutical markets.","zh-TW":"專利在藥品市場創造了高進入壁壘。"},{"en":"Strong brand loyalty is a significant barrier to entry for new competitors.","zh-TW":"強大的品牌忠誠度對新競爭對手是重大的進入壁壘。"}]', '{"plural":"barriers to entry"}', NULL, 5, 572, NULL),
(573, 'base', '/beɪs/', 'noun', '{"zh-TW":["基礎；基地","以…為基礎"],"en":["the lowest part or foundation","to use as a starting point"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"logic":"底部基礎，即「基礎」。"}', 'customer base / base on / base salary', '[{"en":"The company has a large customer base in Asia.","zh-TW":"公司在亞洲擁有龐大的客戶群。"},{"en":"The decision was based on thorough research.","zh-TW":"該決定基於深入研究。"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 1, 573, NULL),
(574, 'base and superstructure', '/beɪs ænd ˈsuːpəˌstrʌktʃər/', 'phrase', '{"zh-TW":["基礎與上層建築"],"en":["the Marxist framework where economic base shapes cultural and political superstructure"]}', NULL, 'Marxist base and superstructure / analyze base and superstructure / base and superstructure theory', '[{"en":"Marxists argue that the economic base determines the cultural and political superstructure.","zh-TW":"馬克思主義者認為經濟基礎決定文化和政治上層建築。"},{"en":"Critics of base and superstructure theory note the relative autonomy of cultural institutions.","zh-TW":"批評基礎與上層建築理論的人指出文化機構的相對自主性。"}]', NULL, NULL, 5, 574, NULL),
(575, 'base salary', '/beɪs ˈsæləri/', 'noun', '{"zh-TW":["基本薪資"],"en":["the fixed amount paid to an employee before bonuses or benefits"]}', NULL, 'negotiate base salary / base salary range', '[{"en":"She negotiated a higher base salary before accepting the offer.","zh-TW":"她在接受邀約前談判了更高的基本薪資。"},{"en":"Base salary is supplemented by performance-linked bonuses.","zh-TW":"基本薪資由績效掛鉤的獎金補充。"}]', NULL, NULL, 4, 575, NULL),
(576, 'baseline', '/ˈbeɪslaɪn/', 'noun', '{"zh-TW":["基準線；基線"],"en":["a starting point used for comparison or measurement of progress"]}', NULL, 'set a baseline / baseline measurement / performance baseline', '[{"en":"The baseline for the project was established at the kickoff meeting.","zh-TW":"項目的基準線在啟動會議上確立。"},{"en":"Performance is measured against the established baseline.","zh-TW":"績效根據既定基準線進行衡量。"}]', '{"adjective":"baseline"}', NULL, 3, 576, 827),
(577, 'basic', '/ˈbeɪsɪk/', 'adjective', '{"zh-TW":["基本的；基礎的"],"en":["forming the most important part"]}', NULL, 'basic knowledge / basic needs', '[{"en":"You need basic computer skills.","zh-TW":"你需要基本的電腦技能。"},{"en":"Food and water are basic needs.","zh-TW":"食物和水是基本需求。"}]', '{"noun":"basics","adverb":"basically"}', NULL, 2, 577, NULL),
(578, 'basis', '/ˈbeɪsɪs/', 'noun', '{"zh-TW":["基礎；依據","基礎；根據"],"en":["the underlying support or foundation for something","the underlying support or foundation"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"suffix":{"text":"-is","meaning":"noun ending (名詞字尾)"},"logic":"底部的根基，即「基礎」。"}', 'on a regular basis / on the basis of; on the basis of / daily basis / regular basis', '[{"en":"Reports are submitted on a weekly basis.","zh-TW":"報告每週提交一次。"},{"en":"Candidates are selected on the basis of experience.","zh-TW":"候選人根據經驗進行篩選。"},{"en":"Employees are evaluated on a regular basis.","zh-TW":"員工定期接受評估。"},{"en":"On what basis did you make that decision?","zh-TW":"你根據什麼做出那個決定？"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 2, 578, 514),
(579, 'basis point', '/ˈbeɪsɪs pɔɪnt/', 'noun', '{"zh-TW":["基點"],"en":["one hundredth of a percentage point, used in finance"]}', NULL, 'move by basis points / basis point spread / one basis point', '[{"en":"A ten basis point increase in interest rates would raise mortgage costs.","zh-TW":"利率提高十個基點將增加抵押貸款成本。"},{"en":"The yield spread widened by fifty basis points after the announcement.","zh-TW":"公告後殖利率利差擴大了五十個基點。"}]', NULL, NULL, 4, 579, NULL),
(580, 'basis points', '/ˈbeɪsɪs pɔɪnts/', 'noun', '{"zh-TW":["基點"],"en":["a unit of measure for interest rates equal to one hundredth of one percent"]}', NULL, 'cut by fifty basis points / raise by twenty-five basis points / measure in basis points', '[{"en":"The central bank raised interest rates by fifty basis points to combat inflation.","zh-TW":"中央銀行將利率提高了五十個基點以對抗通膨。"},{"en":"A spread of two hundred basis points indicates significant credit risk.","zh-TW":"兩百個基點的利差表明存在重大信用風險。"}]', NULL, NULL, 4, 580, NULL),
(581, 'batch', '/bætʃ/', 'noun', '{"zh-TW":["批次；一批"],"en":["a quantity of goods produced in one operation"]}', NULL, 'batch processing / production batch', '[{"en":"The factory produced a batch of 500 units today.","zh-TW":"工廠今天生產了500個單位的一批產品。"},{"en":"Batch processing reduces production costs for large orders.","zh-TW":"批次處理降低了大訂單的生產成本。"}]', '{"verb":"batch","adjective":"batched"}', NULL, 2, 581, NULL),
(582, 'batch processing', '/''bætʃ ˌprɒsesɪŋ/', 'noun', '{"zh-TW":["批次處理；批量加工"],"en":["the processing of a group of items or data at once rather than one at a time"]}', NULL, 'use batch processing / batch processing system / batch processing efficiency', '[{"en":"Batch processing allows the factory to handle large volumes of orders simultaneously.","zh-TW":"批次處理允許工廠同時處理大量訂單。"},{"en":"The IT team runs batch processing jobs at night to minimize disruption during work hours.","zh-TW":"IT團隊在夜間運行批次處理作業，以盡量減少工作時間的中斷。"}]', '{"adjective":"batch","verb":"process"}', NULL, 5, 582, NULL),
(583, 'batch production', '/bætʃ prəˈdʌkʃən/', 'noun', '{"zh-TW":["批量生產"],"en":["manufacturing goods in groups or batches rather than continuously"]}', NULL, 'use batch production / batch production method', '[{"en":"The bakery uses batch production to make different bread types daily.","zh-TW":"麵包店使用批量生產每天製作不同種類的麵包。"},{"en":"Batch production offers flexibility but may result in higher per-unit costs.","zh-TW":"批量生產提供靈活性但可能導致較高的單位成本。"}]', NULL, NULL, 5, 583, NULL),
(584, 'bath', '/bæθ/', 'noun', '{"zh-TW":["洗澡；浴缸","沐浴；浴缸"],"en":["an act of washing the body","washing the body; a container for water"]}', NULL, 'take a bath / bath towel; take a bath / bathroom', '[{"en":"I take a bath every evening.","zh-TW":"我每天晚上洗澡。"},{"en":"The bath is full of hot water.","zh-TW":"浴缸裡滿是熱水。"},{"en":"The bathroom is on the second floor.","zh-TW":"浴室在二樓。"}]', '{"verb":"bathe","noun2":"bathroom"}', NULL, 1, 584, NULL),
(585, 'batting average', '/''bætɪŋ ˌævərɪdʒ/', 'noun', '{"zh-TW":["擊球率；打擊率"],"en":["in baseball, a statistic measuring a batter''s performance based on hits divided by at-bats"]}', NULL, 'maintain a batting average / batting average statistic / high batting average', '[{"en":"He maintained a batting average of over 0.300 throughout the season.","zh-TW":"他在整個賽季保持了超過0.300的擊球率。"},{"en":"A batting average of 0.350 is considered excellent at the professional level.","zh-TW":"在職業水平上，0.350的擊球率被認為是非常優秀的。"}]', NULL, NULL, 5, 585, NULL),
(586, 'batting cage', '/''bætɪŋ keɪdʒ/', 'noun', '{"zh-TW":["打擊練習場；打籠"],"en":["an enclosed area where baseball or softball players practice their batting"]}', NULL, 'practice in the batting cage / use a batting cage / batting cage session', '[{"en":"He spent an hour in the batting cage every morning to improve his swing.","zh-TW":"他每天早上在打擊練習場練習一個小時，以改善他的揮棒。"},{"en":"The training facility included a batting cage, weights room, and indoor track.","zh-TW":"訓練設施包括打擊練習場、重量訓練室和室內跑道。"}]', NULL, NULL, 4, 586, NULL),
(587, 'battle', '/ˈbætəl/', 'noun', '{"zh-TW":["戰鬥；鬥爭"],"en":["a fight between armed forces"]}', NULL, 'battle against / battle field', '[{"en":"The battle lasted three days.","zh-TW":"戰鬥持續了三天。"},{"en":"She won her battle against cancer.","zh-TW":"她贏得了與癌症的鬥爭。"}]', '{"verb":"battle"}', NULL, 2, 587, NULL),
(588, 'beach', '/biːtʃ/', 'noun', '{"zh-TW":["海灘"],"en":["an area of sand beside the sea"]}', NULL, 'on the beach / beach volleyball', '[{"en":"We spent the day at the beach.","zh-TW":"我們在海灘度過了一天。"},{"en":"The beach was crowded in summer.","zh-TW":"夏天海灘很擁擠。"}]', NULL, NULL, 2, 588, NULL),
(589, 'bear', '/beər/', 'verb', '{"zh-TW":["【主要意義-名詞】熊","【次要意義-動詞】承受；忍耐","【次要意義-動詞】產出；帶來（結果）","【次要意義-動詞】朝向某方向移動"],"en":["[primary - noun] a large wild animal","[secondary - verb] to carry a weight or responsibility; to endure","[secondary - verb] to produce something such as fruit or results","[secondary - verb] to move or turn in a particular direction"]}', '{"root":{"text":"bear","meaning":"carry (攜帶)"},"logic":"攜帶重量，即「承擔」。"}', 'bear in mind / bear fruit / bear responsibility / bear left / bear witness', '[{"en":"Please bear in mind that the deadline cannot be extended.","zh-TW":"請記住截止日期無法延後。"},{"en":"The new strategy is beginning to bear fruit after six months.","zh-TW":"新策略在六個月後開始顯現成效。"},{"en":"The company must bear full responsibility for the product defect.","zh-TW":"公司必須對產品缺陷承擔全部責任。"}]', '{"noun":"bearing","adjective":"bearable"}', 'bear 作動詞有多個高頻用法：bear in mind（記住），bear fruit（結出成果），bear responsibility（承擔責任），這些均為 TOEIC 商業文章必考表達，與名詞「熊」完全無關。', 1, 589, NULL),
(590, 'bear market', '/beər ˈmɑːrkɪt/', 'noun', '{"zh-TW":["空頭市場；熊市"],"en":["a prolonged period of falling stock prices"]}', NULL, 'enter a bear market / bear market conditions / survive a bear market', '[{"en":"The bear market wiped out years of gains.","zh-TW":"熊市抹去了多年的收益。"},{"en":"Defensive stocks performed better during the bear market.","zh-TW":"防禦型股票在熊市中表現較好。"}]', '{"antonym":"bull market"}', NULL, 4, 590, NULL),
(591, 'bear out', '/beər aʊt/', 'phrasal verb', '{"zh-TW":["【主要意義】證實；支持；佐證"],"en":["[primary] to confirm or support the truth of something","[secondary] to justify or vindicate a claim or statement"]}', NULL, 'bear out a claim / bear out a theory / bear someone out', '[{"en":"The financial data bears out the auditor''s concerns about overspending.","zh-TW":"財務數據證實了審計人員對超支的擔憂。"},{"en":"His performance in the interview bore out our initial impression of him.","zh-TW":"他在面試中的表現證實了我們對他的最初印象。"},{"en":"The results bear out the hypothesis proposed last year.","zh-TW":"這些結果支持了去年提出的假設。"}]', '{"verb":"bear, bears, bore, borne"}', 'bear out 意為「證實/佐證」，常出現在 TOEIC 閱讀的報告分析或研究結論語境中，與 bear（熊）毫無關聯。', 3, 591, NULL),
(592, 'beat', '/biːt/', 'verb', '{"zh-TW":["打敗；跳動"],"en":["to defeat someone; to make a rhythm"]}', NULL, 'beat the record / heartbeat', '[{"en":"Our team beat theirs 3-1.","zh-TW":"我們隊以3比1打敗了他們。"},{"en":"My heart was beating fast.","zh-TW":"我的心跳得很快。"}]', '{"noun":"beat"}', NULL, 1, 592, NULL),
(593, 'beautiful', '/ˈbjuːtɪfəl/', 'adjective', '{"zh-TW":["美麗的","美麗的；漂亮的","美麗的；美好的"],"en":["very pleasing to look at or experience","very attractive or pleasing","very attractive; giving great pleasure"]}', NULL, 'beautiful weather / beautiful design; beautiful scenery / beautiful day; beautiful scenery/weather/music', '[{"en":"The office has a beautiful view.","zh-TW":"辦公室有很美的景觀。"},{"en":"Thank you for this beautiful gift.","zh-TW":"謝謝你這份美麗的禮物。"},{"en":"What a beautiful sunset!","zh-TW":"多美的日落啊！"},{"en":"She has a beautiful voice.","zh-TW":"她有一副美麗的嗓音。"},{"en":"What a beautiful day!","zh-TW":"多麼美好的一天！"},{"en":"She wore a beautiful dress.","zh-TW":"她穿了一件漂亮的洋裝。"}]', '{"adjective":"beautiful","noun":"beauty","adverb":"beautifully","verb":"beautify"}', NULL, 3, 593, NULL),
(594, 'because', '/bɪˈkɒz/', 'conjunction', '{"zh-TW":["因為"],"en":["for the reason that"]}', NULL, 'because of / just because', '[{"en":"I stayed home because I was sick.","zh-TW":"我因為生病待在家裡。"},{"en":"The game was canceled because of rain.","zh-TW":"比賽因為下雨被取消了。"}]', NULL, NULL, 3, 594, NULL),
(595, 'become', '/bɪˈkʌm/', 'verb', '{"zh-TW":["變成；成為","成為；變得"],"en":["to begin to be; to grow to be","to begin to be something","to begin to be; to start being"]}', NULL, 'become aware / become available; become aware / become friends; become + adj/noun', '[{"en":"He became the new manager.","zh-TW":"他成為了新經理。"},{"en":"The product has become very popular.","zh-TW":"這個產品變得非常受歡迎。"},{"en":"She became a doctor.","zh-TW":"她成為了一名醫生。"},{"en":"It''s becoming colder.","zh-TW":"天氣越來越冷了。"},{"en":"The situation became worse.","zh-TW":"情況變得更糟了。"}]', '{"verb":"become"}', NULL, 2, 595, NULL),
(596, 'bed', '/bɛd/', 'noun', '{"zh-TW":["床","床；花壇"],"en":["a piece of furniture for sleeping","a piece of furniture for sleeping on"]}', NULL, 'go to bed / in bed; go to bed / make the bed / bed and breakfast', '[{"en":"Time to go to bed.","zh-TW":"該上床睡覺了。"},{"en":"He stayed in bed all day.","zh-TW":"他整天待在床上。"},{"en":"I usually go to bed at 11 PM.","zh-TW":"我通常晚上11點上床睡覺。"},{"en":"Please make your bed.","zh-TW":"請整理你的床。"}]', '{"noun2":"bedroom","noun3":"bedding","noun":"bedding, bedroom"}', NULL, 1, 596, NULL),
(597, 'bed and breakfast', '/bɛd ænd ˈbrɛkfəst/', 'noun', '{"zh-TW":["民宿；住宿含早餐"],"en":["accommodation with an overnight stay and breakfast included"]}', NULL, 'stay at a bed and breakfast / charming bed and breakfast', '[{"en":"They chose a charming bed and breakfast in the countryside.","zh-TW":"他們選擇了鄉村的一家迷人的民宿。"},{"en":"A bed and breakfast is usually smaller and more personal than a hotel.","zh-TW":"民宿通常比飯店規模更小且更具個人特色。"}]', '{"abbreviation":"B&B"}', NULL, 5, 597, NULL),
(598, 'before', '/bɪˈfɔːr/', 'preposition, conjunction, adverb', '{"zh-TW":["在...之前"],"en":["earlier than; at an earlier time"]}', NULL, 'before + V-ing / the day before', '[{"en":"Finish your work before the deadline.","zh-TW":"在截止日期前完成你的工作。"},{"en":"I''ve never been here before.","zh-TW":"我以前從未來過這裡。"}]', NULL, NULL, 2, 598, NULL),
(599, 'begin', '/bɪˈɡɪn/', 'verb', '{"zh-TW":["開始","開始；著手"],"en":["to start","to start doing something","to start; to do the first part of something"]}', NULL, 'begin with / to begin with; begin to do / begin doing / begin with', '[{"en":"The workshop begins at 10 a.m.","zh-TW":"研習會在上午10點開始。"},{"en":"Let us begin with the agenda.","zh-TW":"讓我們從議程開始。"},{"en":"The meeting begins at 9.","zh-TW":"會議9點開始。"},{"en":"Let''s begin with introductions.","zh-TW":"讓我們從自我介紹開始。"},{"en":"The meeting begins at 9 AM.","zh-TW":"會議上午九點開始。"},{"en":"Let''s begin with the first item on the agenda.","zh-TW":"讓我們從議程的第一項開始。"}]', '{"verb":"begin","noun":"beginning","noun2":"beginner"}', NULL, 2, 599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(600, 'behalf', '/bɪˈhɑːf/', 'noun', '{"zh-TW":["代表；為了…的利益","代表"],"en":["in the interest of; as a representative of"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"half","meaning":"side (邊)"},"logic":"在某人的邊（一方），即「代表」。"}', 'on behalf of / on sb''s behalf; on behalf of / act on someone''s behalf', '[{"en":"I''m writing on behalf of the marketing department.","zh-TW":"我代表行銷部門寫信。"},{"en":"The lawyer acted on behalf of the client.","zh-TW":"律師代表客戶行事。"},{"en":"I am writing on behalf of my client.","zh-TW":"我代表我的客戶寫信。"},{"en":"She accepted the award on behalf of the team.","zh-TW":"她代表團隊接受了獎項。"}]', NULL, NULL, 2, 600, NULL),
(601, 'behave', '/bɪˈheɪv/', 'verb', '{"zh-TW":["行為；表現"],"en":["to act in a particular way","to conduct oneself properly"]}', '{"prefix":{"text":"be-","meaning":"thoroughly (徹底)"},"root":{"text":"have","meaning":"hold oneself (持有自己)"},"logic":"徹底持有自己的方式，即「行為」。"}', 'behave professionally / consumer behavior', '[{"en":"Employees are expected to behave professionally.","zh-TW":"員工應表現專業。"},{"en":"Market conditions cause consumers to behave differently.","zh-TW":"市場條件使消費者行為有所不同。"}]', '{"noun":"behavior"}', NULL, 2, 601, NULL),
(602, 'behavioral economics', '/bɪˌheɪvjərəl ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["行為經濟學"],"en":["a field that combines economic and psychological insights to explain decision-making"]}', NULL, 'principles of behavioral economics / apply behavioral economics / behavioral economics research', '[{"en":"Behavioral economics shows that people often act irrationally in financial decisions.","zh-TW":"行為經濟學表明，人們在金融決策中常常表現出非理性行為。"},{"en":"Nudge theory, a branch of behavioral economics, improves health outcomes.","zh-TW":"輕推理論是行為經濟學的一個分支，可改善健康結果。"}]', NULL, NULL, 5, 602, NULL),
(603, 'behavioral finance', '/bɪˈheɪvjərəl ˈfaɪnæns/', 'noun', '{"zh-TW":["行為金融學"],"en":["the study of psychological influences on investors and financial markets"]}', NULL, 'apply behavioral finance / principles of behavioral finance / behavioral finance research', '[{"en":"Behavioral finance explains why investors make irrational decisions driven by emotion.","zh-TW":"行為金融學解釋了為什麼投資者會因情緒驅動而做出非理性決策。"},{"en":"Loss aversion, a concept from behavioral finance, causes investors to hold losing positions too long.","zh-TW":"損失厭惡是行為金融學中的一個概念，導致投資者持有虧損頭寸太長時間。"}]', NULL, NULL, 5, 603, NULL),
(604, 'behind', '/bɪˈhaɪnd/', 'preposition', '{"zh-TW":["在…後面；落後","在…後面","在...後面；落後"],"en":["at the back of","less advanced than","at the back of; not making enough progress"]}', NULL, 'fall behind / behind schedule; behind schedule / fall behind; behind schedule / fall behind / leave behind', '[{"en":"The project is behind schedule.","zh-TW":"專案進度落後了。"},{"en":"Who is behind this decision?","zh-TW":"誰在這個決定背後？"},{"en":"The cat hid behind the sofa.","zh-TW":"貓躲在沙發後面。"},{"en":"We''re behind schedule.","zh-TW":"我們落後於進度了。"},{"en":"The garden is behind the house.","zh-TW":"花園在房子後面。"},{"en":"We''re behind schedule on this project.","zh-TW":"我們這個專案進度落後。"}]', '{"preposition":"behind","adverb":"behind"}', NULL, 2, 604, NULL),
(605, 'believe', '/bɪˈliːv/', 'verb', '{"zh-TW":["相信；認為"],"en":["to think something is true","to have confidence in","to accept as true","to think something is true; to have faith"]}', NULL, 'believe in / hard to believe; believe in / believe it or not', '[{"en":"I believe this strategy will work.","zh-TW":"我相信這個策略會成功。"},{"en":"We believe in teamwork.","zh-TW":"我們相信團隊合作。"},{"en":"I believe you''re right.","zh-TW":"我相信你是對的。"},{"en":"Do you believe in ghosts?","zh-TW":"你相信有鬼嗎？"},{"en":"I believe this plan will work.","zh-TW":"我相信這個計畫會成功。"},{"en":"She doesn''t believe in ghosts.","zh-TW":"她不相信鬼。"}]', '{"verb":"believe","noun":"belief","adjective":"believable","adjective2":"unbelievable"}', NULL, 3, 605, NULL),
(606, 'bellhop', '/''belhɒp/', 'noun', '{"zh-TW":["行李服務員；飯店服務生"],"en":["a hotel worker who carries bags and runs errands for guests"]}', NULL, 'tip the bellhop / bellhop service / call the bellhop', '[{"en":"The bellhop helped carry our luggage to the room and explained the hotel facilities.","zh-TW":"行李服務員幫我們把行李搬到房間，並介紹了飯店設施。"},{"en":"We gave the bellhop a generous tip for his quick and courteous service.","zh-TW":"我們給了行李服務員豐厚的小費，感謝他快速而有禮貌的服務。"}]', NULL, NULL, 3, 606, NULL),
(607, 'bellwether', '/ˈbelwɛðər/', 'noun', '{"zh-TW":["風向標；領頭羊"],"en":["a leader or indicator that is a leading indicator of a broader trend"]}', NULL, 'bellwether stock / economic bellwether / bellwether industry', '[{"en":"Technology stocks often serve as a bellwether for the broader market.","zh-TW":"科技股通常作為更廣泛市場的風向標。"},{"en":"This region is considered a bellwether for national election outcomes.","zh-TW":"該地區被視為全國選舉結果的風向標。"}]', NULL, NULL, 4, 607, NULL),
(608, 'belong', '/bɪˈlɒŋ/', 'verb', '{"zh-TW":["屬於","屬於；適合在"],"en":["to be the property of","to be the property of; to be in the right place"]}', NULL, 'belong to / a sense of belonging', '[{"en":"This book belongs to me.","zh-TW":"這本書是我的。"},{"en":"She felt she didn''t belong.","zh-TW":"她覺得自己不屬於這裡。"},{"en":"These files belong in the cabinet.","zh-TW":"這些文件應該放在櫃子裡。"}]', '{"noun":"belonging"}', NULL, 2, 608, NULL),
(609, 'below', '/bɪˈloʊ/', 'preposition', '{"zh-TW":["在…下面","在...下面；低於"],"en":["at a lower level than","at a lower level than; less than"]}', NULL, 'below average / see below; below average / below zero', '[{"en":"The temperature dropped below zero.","zh-TW":"溫度降到了零度以下。"},{"en":"See the chart below.","zh-TW":"請看下面的圖表。"},{"en":"The temperature dropped below zero.","zh-TW":"氣溫降到零度以下。"},{"en":"See the chart below.","zh-TW":"請見下方圖表。"}]', NULL, NULL, 2, 609, NULL),
(610, 'below the line', '/bɪˈloʊ ðə laɪn/', 'adjective', '{"zh-TW":["線下的；促銷活動的"],"en":["relating to direct, targeted marketing such as promotions and events"]}', NULL, 'below-the-line advertising / below-the-line promotion', '[{"en":"Below-the-line campaigns use direct mail, promotions, and events.","zh-TW":"線下活動使用直郵、促銷和活動。"},{"en":"A below-the-line campaign targeted specific customer segments with coupons.","zh-TW":"線下活動通過優惠券針對特定客戶群體。"}]', '{"opposite":"above-the-line"}', NULL, 5, 610, NULL),
(611, 'benchmark', '/ˈbentʃmɑːrk/', 'noun', '{"zh-TW":["基準；標竿"],"en":["a standard or point of reference for comparison","a standard for comparison"]}', '{"root":{"text":"bench","meaning":"bench (長凳)"},"suffix":{"text":"mark","meaning":"mark (標記)"},"logic":"長凳上的標記（測量基準），即「基準」。"}', 'industry benchmark / set a benchmark / benchmark against', '[{"en":"Our service quality sets the benchmark in the industry.","zh-TW":"我們的服務品質樹立了行業基準。"},{"en":"We benchmark our performance against competitors.","zh-TW":"我們以競爭對手為基準評估績效。"},{"en":"This sets a new benchmark for quality.","zh-TW":"這為品質設立了新的標竿。"},{"en":"We measure performance against industry benchmarks.","zh-TW":"我們以產業基準來衡量績效。"}]', '{"verb":"benchmark","noun":"benchmark","noun2":"benchmarking"}', NULL, 3, 611, 278),
(612, 'benchmark against', '/ˈbentʃmɑːrk əˈɡenst/', 'verb', '{"zh-TW":["對標；與...比較基準"],"en":["to compare performance against a standard or competitor"]}', NULL, 'benchmark against industry peers / benchmark against competitors', '[{"en":"The company benchmarks against global best practices annually.","zh-TW":"公司每年與全球最佳實踐對標。"},{"en":"Management benchmarked costs against three leading competitors.","zh-TW":"管理層將成本與三家主要競爭對手進行對標。"}]', NULL, NULL, 5, 612, NULL),
(613, 'benchmark analysis', '/ˈbentʃmɑːrk əˈnæləsɪs/', 'noun', '{"zh-TW":["基準分析"],"en":["the process of comparing performance metrics against a standard or competitor"]}', NULL, 'conduct benchmark analysis / benchmark analysis results', '[{"en":"A benchmark analysis revealed the company lags peers in digital adoption.","zh-TW":"基準分析顯示公司在數位採用方面落後於同業。"},{"en":"Benchmark analysis is part of the annual strategic review process.","zh-TW":"基準分析是年度戰略審查流程的一部分。"}]', NULL, NULL, 5, 613, NULL),
(614, 'benchmark comparison', '/''bentʃˌmɑːrk kəmˌpærɪsən/', 'noun', '{"zh-TW":["基準比較；標準對照"],"en":["an evaluation that measures performance against an established standard or reference point"]}', NULL, 'conduct benchmark comparison / use benchmark comparison / benchmark comparison report', '[{"en":"The quarterly benchmark comparison showed that performance exceeded industry average.","zh-TW":"季度基準比較顯示業績超過了行業平均水平。"},{"en":"Benchmark comparisons help organizations identify areas for improvement.","zh-TW":"基準比較幫助組織識別需要改進的領域。"}]', NULL, NULL, 5, 614, NULL),
(615, 'benchmark data', '/''bentʃmɑːrk ˌdeɪtə/', 'noun', '{"zh-TW":["基準數據"],"en":["data used as a reference point against which performance or progress can be measured"]}', NULL, 'collect benchmark data / analyze benchmark data / use benchmark data', '[{"en":"The study collected benchmark data on student performance before implementing the new curriculum.","zh-TW":"研究在實施新課程之前收集了學生表現的基準數據。"},{"en":"Benchmark data allows companies to compare their efficiency with industry standards.","zh-TW":"基準數據使公司能夠將其效率與行業標準進行比較。"}]', '{"noun":"benchmark"}', NULL, 5, 615, NULL),
(616, 'benchmark index', '/ˈbentʃmɑːrk ˈɪndeks/', 'noun', '{"zh-TW":["基準指數"],"en":["a standard index used to measure and compare the performance of investments"]}', NULL, 'track the benchmark index / outperform the benchmark index', '[{"en":"The fund consistently outperformed the benchmark index over five years.","zh-TW":"該基金在五年內持續超越了基準指數。"},{"en":"Portfolio managers are measured against an appropriate benchmark index.","zh-TW":"投資組合管理人按適當的基準指數衡量績效。"}]', NULL, NULL, 5, 616, NULL),
(617, 'benchmark interest rate', '/ˈbentʃmɑːrk ˈɪntrɪst reɪt/', 'noun', '{"zh-TW":["基準利率"],"en":["the standard interest rate set by a central bank that influences other rates"]}', NULL, 'set the benchmark interest rate / below the benchmark interest rate', '[{"en":"The central bank raised the benchmark interest rate to curb inflation.","zh-TW":"中央銀行提高了基準利率以抑制通貨膨脹。"},{"en":"Lending rates are typically set above the benchmark interest rate.","zh-TW":"貸款利率通常設定在基準利率之上。"}]', NULL, NULL, 5, 617, NULL),
(618, 'benchmark performance', '/''bentʃmɑːrk pəˌfɔːrməns/', 'noun', '{"zh-TW":["基準表現；標竿績效"],"en":["a level of performance used as a standard against which others can be measured"]}', NULL, 'exceed benchmark performance / measure benchmark performance / set a benchmark performance', '[{"en":"The team''s benchmark performance exceeded expectations in every category.","zh-TW":"團隊的基準表現在每個類別中都超出了預期。"},{"en":"Regular benchmark performance reviews help teams stay on track with their goals.","zh-TW":"定期基準績效審查幫助團隊在實現目標方面保持正軌。"}]', NULL, NULL, 5, 618, NULL),
(619, 'benchmark rate', '/ˈbentʃmɑːrk reɪt/', 'noun', '{"zh-TW":["基準利率"],"en":["an interest rate used as a reference for pricing other financial products"]}', NULL, 'set a benchmark rate / floating rate tied to benchmark / benchmark rate change', '[{"en":"LIBOR was replaced by SOFR as the primary benchmark rate.","zh-TW":"LIBOR被SOFR取代成為主要基準利率。"},{"en":"The loan is priced at two hundred basis points above the benchmark rate.","zh-TW":"貸款定價為基準利率上加兩百個基點。"}]', NULL, NULL, 5, 619, NULL),
(620, 'benchmark standard', '/''bentʃmɑːrk ˌstændərd/', 'noun', '{"zh-TW":["基準標準"],"en":["an established level of quality or attainment used as a reference point for comparison"]}', NULL, 'set a benchmark standard / meet a benchmark standard / exceed the benchmark standard', '[{"en":"The factory established benchmark standards for quality control at every stage of production.","zh-TW":"工廠在生產的每個階段建立了品質控制的基準標準。"},{"en":"Meeting the industry benchmark standard is essential for gaining customer trust.","zh-TW":"達到行業基準標準對於獲得客戶信任至關重要。"}]', NULL, NULL, 5, 620, NULL),
(621, 'benchmark test', '/ˈbɛntʃmɑːrk tɛst/', 'noun', '{"zh-TW":["基準測試"],"en":["a standard test used to measure performance"]}', NULL, 'run a benchmark test / benchmark test results', '[{"en":"The IT team ran a benchmark test on the new servers.","zh-TW":"IT團隊在新伺服器上進行了基準測試。"},{"en":"Benchmark tests help compare performance across systems.","zh-TW":"基準測試有助於比較各系統的性能。"}]', NULL, NULL, 5, 621, NULL),
(622, 'benchmarking', '/ˈbentʃˌmɑːrkɪŋ/', 'noun', '{"zh-TW":["基準分析；標竿學習"],"en":["comparing performance metrics to industry best practices"]}', NULL, 'competitive benchmarking / internal benchmarking', '[{"en":"Benchmarking revealed we lagged behind competitors in speed.","zh-TW":"基準分析顯示我們在速度上落後於競爭對手。"},{"en":"We use benchmarking to identify areas for improvement.","zh-TW":"我們使用基準分析來識別改進領域。"}]', '{"verb":"benchmark","noun":"benchmark"}', NULL, 4, 622, 753),
(623, 'benchmarking exercise', '/ˈbentʃmɑːrkɪŋ ˈeksəsaɪz/', 'noun', '{"zh-TW":["標竿比較練習；基準評估"],"en":["an activity comparing processes or performance against best-in-class standards"]}', NULL, 'conduct a benchmarking exercise / benchmarking exercise results', '[{"en":"The benchmarking exercise identified areas where the company underperformed.","zh-TW":"標竿比較練習確定了公司表現不佳的領域。"},{"en":"A regular benchmarking exercise helps drive continuous improvement.","zh-TW":"定期的標竿比較練習有助於推動持續改進。"}]', NULL, NULL, 5, 623, NULL),
(624, 'benchmarking study', '/ˈbentʃmɑːrkɪŋ ˈstʌdi/', 'noun', '{"zh-TW":["標竿研究；基準比較研究"],"en":["an analysis comparing a company performance to industry peers"]}', NULL, 'conduct a benchmarking study / publish a benchmarking study', '[{"en":"The consultants conducted a benchmarking study on HR practices.","zh-TW":"顧問們對人力資源實踐進行了標竿研究。"},{"en":"The benchmarking study revealed gaps in our customer service scores.","zh-TW":"標竿研究揭示了我們客戶服務評分中的差距。"}]', NULL, NULL, 5, 624, NULL),
(625, 'bend', '/bɛnd/', 'verb', '{"zh-TW":["彎曲；屈身"],"en":["to make something curved"]}', NULL, 'bend down / bend the rules', '[{"en":"Bend your knees slightly.","zh-TW":"稍微彎曲膝蓋。"},{"en":"She bent down to pick it up.","zh-TW":"她彎腰撿起來。"}]', NULL, NULL, 1, 625, NULL),
(626, 'beneath', '/bɪˈniːθ/', 'preposition', '{"zh-TW":["在…下方"],"en":["in or to a lower position than; under"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"neath","meaning":"below (下方)"},"logic":"在下方的位置。"}', 'beneath the surface / beneath one''s dignity', '[{"en":"The treasure was buried beneath the old tree.","zh-TW":"寶藏埋在老樹下方。"},{"en":"Beneath the surface, there are many problems.","zh-TW":"表面之下有許多問題。"}]', NULL, NULL, 3, 626, NULL),
(627, 'beneficent', '/bɪˈnefɪsənt/', 'adjective', '{"zh-TW":["仁慈的；行善的"],"en":["generous or doing good; conferring benefits"]}', NULL, 'beneficent policy / beneficent organization / beneficent intent', '[{"en":"A beneficent climate policy would reduce emissions while creating jobs.","zh-TW":"一項仁慈的氣候政策將在創造就業機會的同時減少排放。"},{"en":"The foundation is known for its beneficent work in education and healthcare.","zh-TW":"該基金會因其在教育和醫療保健方面的善舉而聞名。"}]', '{"noun":"beneficence","adverb":"beneficently"}', NULL, 4, 627, NULL),
(628, 'beneficiary', '/ˌbenɪˈfɪʃiəri/', 'noun', '{"zh-TW":["受益人"],"en":["a person or entity entitled to receive benefits from a policy or trust"]}', NULL, 'name a beneficiary / policy beneficiary / trust beneficiary', '[{"en":"She named her children as beneficiaries of her life insurance policy.","zh-TW":"她將子女列為人壽保險保單的受益人。"},{"en":"The beneficiary received the full payout upon the policyholder''s death.","zh-TW":"受益人在保單持有人死亡後獲得了全額賠付。"}]', '{"plural":"beneficiaries"}', NULL, 4, 628, NULL),
(629, 'benefit', '/ˈbenɪfɪt/', 'noun', '{"zh-TW":["利益；好處","福利"],"en":["an advantage or profit gained","a payment made by the state or employer"]}', '{"root":{"text":"bene","meaning":"good (好)"},"suffix":{"text":"-fit","meaning":"do/make (做)"},"logic":"做好事帶來的，即「利益」。"}', 'benefit from / employee benefits / mutual benefit', '[{"en":"Both parties will benefit from this partnership.","zh-TW":"雙方都將從這個合作中受益。"},{"en":"The company offers excellent employee benefits.","zh-TW":"公司提供優秀的員工福利。"}]', '{"adjective":"beneficial"}', NULL, 3, 629, 12),
(630, 'benefit period', '/ˈbɛnɪfɪt ˈpɪəriəd/', 'noun', '{"zh-TW":["保險給付期間"],"en":["the length of time insurance benefits are payable"]}', NULL, 'annual benefit period / benefit period limit', '[{"en":"Your benefit period begins on the date of enrollment.","zh-TW":"您的保險給付期間從入保日期開始計算。"},{"en":"Hospitalization is covered during the benefit period.","zh-TW":"住院費用在保險給付期間內承保。"}]', NULL, NULL, 5, 630, NULL),
(631, 'benefits', '/ˈbɛnɪfɪts/', 'noun', '{"zh-TW":["福利；員工福利"],"en":["non-wage compensation provided to employees"]}', NULL, 'employee benefits / benefits package', '[{"en":"The benefits package includes health insurance and a pension.","zh-TW":"福利待遇包括健康保險和退休金。"},{"en":"Many employees value good benefits over higher salaries.","zh-TW":"許多員工重視良好福利勝過更高薪資。"}]', '{"verb":"benefit","adjective":"beneficial"}', NULL, 3, 631, NULL),
(632, 'benign', '/bɪˈnaɪn/', 'adjective', '{"zh-TW":["良性的；無害的"],"en":["(of a tumor or condition) not harmful or cancerous"]}', NULL, 'benign tumor / benign growth / benign condition', '[{"en":"The biopsy confirmed that the lump was benign.","zh-TW":"活檢確認腫塊是良性的。"},{"en":"Benign neglect of minor symptoms can sometimes allow self-healing.","zh-TW":"對輕微症狀的良性忽視有時可以讓自愈發生。"}]', '{"antonym":"malignant","adverb":"benignly"}', NULL, 2, 632, NULL),
(633, 'beside', '/bɪˈsaɪd/', 'preposition', '{"zh-TW":["在…旁邊"],"en":["next to; at the side of"]}', NULL, 'beside the point / sit beside', '[{"en":"Come and sit beside me.","zh-TW":"來坐在我旁邊。"},{"en":"That''s beside the point.","zh-TW":"那不是重點。"}]', NULL, NULL, 2, 633, NULL),
(634, 'besides', '/bɪˈsaɪdz/', 'preposition', '{"zh-TW":["除了…之外"],"en":["in addition to; apart from"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"sides","meaning":"sides (邊)"},"logic":"在旁邊之外還有，即「除了…之外」。"}', 'besides that / besides me', '[{"en":"Besides English, she speaks French and German.","zh-TW":"除了英語，她還會說法語和德語。"},{"en":"Besides the cost, there are other concerns.","zh-TW":"除了費用之外，還有其他顧慮。"}]', NULL, NULL, 3, 634, NULL),
(635, 'best', '/best/', 'adjective, adverb, noun', '{"zh-TW":["最好的；最佳地"],"en":["of the highest quality; most well"]}', NULL, 'do one''s best / at best / best practice', '[{"en":"She is the best student in class.","zh-TW":"她是班上最好的學生。"},{"en":"We did our best to finish on time.","zh-TW":"我們盡了最大努力準時完成。"}]', NULL, NULL, 1, 635, NULL),
(636, 'best practice', '/best ˈpræktɪs/', 'noun', '{"zh-TW":["最佳實踐；最佳做法"],"en":["a method recognized as most effective in achieving results"]}', NULL, 'industry best practice / adopt best practices / share best practices', '[{"en":"We adopted best practices from leading companies worldwide.","zh-TW":"我們採用了全球領先公司的最佳實踐。"},{"en":"Best practices in cybersecurity should be followed strictly.","zh-TW":"應嚴格遵循網路安全最佳實踐。"}]', NULL, NULL, 5, 636, NULL),
(637, 'best practices', '/best ˈpræktɪsɪz/', 'noun', '{"zh-TW":["最佳實踐；最佳作法"],"en":["methods or techniques proven most effective in achieving a result"]}', NULL, 'adopt best practices / industry best practices', '[{"en":"The company adopted best practices from the manufacturing sector.","zh-TW":"公司採用了製造業的最佳實踐。"},{"en":"Sharing best practices across departments improves overall performance.","zh-TW":"跨部門分享最佳實踐改善了整體績效。"}]', NULL, NULL, 5, 637, NULL),
(638, 'beta', '/ˈbeɪtə/', 'noun', '{"zh-TW":["測試版"],"en":["an early version of a product for testing"]}', NULL, 'beta version / beta testing', '[{"en":"The app is still in beta.","zh-TW":"這個應用程式還在測試階段。"},{"en":"Beta testers found several bugs.","zh-TW":"測試用戶發現了幾個錯誤。"}]', NULL, NULL, 1, 638, NULL),
(639, 'better', '/ˈbetər/', 'adjective, adverb', '{"zh-TW":["更好的；更好地"],"en":["of a higher standard; more well"]}', NULL, 'had better (最好...) / get better', '[{"en":"This solution is better than the last one.","zh-TW":"這個方案比上一個好。"},{"en":"You''d better leave now.","zh-TW":"你最好現在離開。"}]', '{"verb":"better"}', NULL, 2, 639, NULL),
(640, 'between', '/bɪˈtwiːn/', 'preposition', '{"zh-TW":["在…之間","在...之間（兩者）"],"en":["in the space or time separating two things","in the space separating two things"]}', NULL, 'between meetings / in between; between you and me / in between; between A and B / in between', '[{"en":"The interview is between 2 and 3 p.m.","zh-TW":"面試在下午2點到3點之間。"},{"en":"Choose between the two options.","zh-TW":"在兩個選項之間做選擇。"},{"en":"The shop is between the bank and the post office.","zh-TW":"商店在銀行和郵局之間。"},{"en":"Between you and me, I don''t like him.","zh-TW":"你我之間說，我不喜歡他。"},{"en":"The meeting is between 2 and 4 PM.","zh-TW":"會議在下午2點到4點之間。"}]', '{"preposition":"between"}', NULL, 3, 640, NULL),
(641, 'beverage', '/ˈbɛvərɪdʒ/', 'noun', '{"zh-TW":["飲料；飲品"],"en":["a drink of any type"]}', NULL, 'hot beverage / cold beverage', '[{"en":"The beverage menu includes both alcoholic and non-alcoholic options.","zh-TW":"飲料菜單包含酒精和非酒精選項。"},{"en":"Complimentary beverages are served during the flight.","zh-TW":"飛行期間提供免費飲料。"}]', NULL, NULL, 3, 641, NULL),
(642, 'beyond', '/bɪˈjɒnd/', 'preposition', '{"zh-TW":["超越；在…之外"],"en":["further away than; outside the limits of"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"yond","meaning":"that side (那邊)"},"logic":"在那邊之外，即「超越」。"}', 'beyond expectations / beyond doubt / go beyond', '[{"en":"The results went beyond our expectations.","zh-TW":"結果超出了我們的預期。"},{"en":"This task is beyond my abilities.","zh-TW":"這項任務超出了我的能力。"}]', NULL, NULL, 2, 642, NULL),
(643, 'biannual', '/baɪˈænjuəl/', 'adjective', '{"zh-TW":["每兩年一次的；每年兩次的"],"en":["occurring twice a year or every two years"]}', NULL, 'biannual review / biannual report', '[{"en":"A biannual performance review is conducted in June and December.","zh-TW":"每年兩次的績效審查在六月和十二月進行。"},{"en":"The board meets for a biannual strategic assessment.","zh-TW":"董事會每兩年進行一次戰略評估。"}]', '{"adverb":"biannually"}', NULL, 3, 643, NULL),
(644, 'bid', '/bɪd/', 'noun', '{"zh-TW":["出價；投標"],"en":["an offer of a price for something","an attempt to achieve something"]}', '{"root":{"text":"bid","meaning":"offer (提供)"},"logic":"提供價格，即「出價」。"}', 'submit a bid / highest bidder', '[{"en":"Three companies submitted bids for the project.","zh-TW":"三家公司對該專案提交了投標。"},{"en":"The winning bid was $4.5 million.","zh-TW":"中標金額為450萬美元。"}]', '{"noun":"bidder"}', NULL, 1, 644, NULL),
(645, 'bid bond', '/bɪd bɒnd/', 'noun', '{"zh-TW":["投標保函"],"en":["a guarantee that a bidder will enter into a contract if selected"]}', NULL, 'submit a bid bond / bid bond requirement', '[{"en":"A bid bond of 2% of the contract value was required.","zh-TW":"要求合約價值2%的投標保函。"},{"en":"The bid bond protects the client if the winning bidder withdraws.","zh-TW":"如果中標者撤回，投標保函保護了客戶。"}]', NULL, NULL, 3, 645, NULL),
(646, 'bid document', '/bɪd ˈdɒkjʊmənt/', 'noun', '{"zh-TW":["投標文件"],"en":["a formal submission outlining a company offer to win a contract"]}', NULL, 'prepare bid documents / submit bid documents', '[{"en":"All bid documents must be received before the 5 PM deadline.","zh-TW":"所有投標文件必須在下午5點截止日期前收到。"},{"en":"The bid documents included technical specifications and pricing.","zh-TW":"投標文件包括技術規格和定價。"}]', NULL, NULL, 4, 646, NULL),
(647, 'bid-ask spread', '/bɪd æsk spred/', 'noun', '{"zh-TW":["買賣差價"],"en":["the difference between the highest price a buyer will pay and the lowest a seller will accept"]}', NULL, 'narrow bid-ask spread / wide bid-ask spread / bid-ask spread compression', '[{"en":"A narrow bid-ask spread indicates a liquid and efficient market.","zh-TW":"較窄的買賣差價表明市場流動性好且效率高。"},{"en":"The bid-ask spread widens during periods of high volatility.","zh-TW":"買賣差價在高波動時期擴大。"}]', NULL, NULL, 5, 647, NULL),
(648, 'biennale', '/biˈenɑːli/', 'noun', '{"zh-TW":["雙年展"],"en":["an international art exhibition held every two years"]}', NULL, 'Venice Biennale / art biennale / participate in biennale', '[{"en":"The Venice Biennale is the world''s most prestigious contemporary art exhibition.","zh-TW":"威尼斯雙年展是世界上最負盛名的當代藝術展覽。"},{"en":"The artist was selected to represent her country at the biennale.","zh-TW":"這位藝術家被選中代表她的國家參加雙年展。"}]', NULL, NULL, 3, 648, NULL),
(649, 'bifurcate', '/ˈbaɪfərkeɪt/', 'verb', '{"zh-TW":["分叉；分成兩部分"],"en":["to divide into two branches or parts"]}', NULL, 'bifurcate the analysis / bifurcate into categories / bifurcate data', '[{"en":"The research bifurcates into qualitative and quantitative streams.","zh-TW":"研究分為質性和量化兩條路線。"},{"en":"The argument bifurcates around two competing theories.","zh-TW":"該論點圍繞兩種競爭理論分叉。"}]', '{"noun":"bifurcation","adjective":"bifurcated"}', NULL, 3, 649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(650, 'big', '/bɪɡ/', 'adjective', '{"zh-TW":["大的","大的；重要的"],"en":["of considerable size or extent","large in size; important"]}', NULL, 'big deal / big picture; a big deal / big business', '[{"en":"They live in a big house.","zh-TW":"他們住在一棟大房子裡。"},{"en":"It''s no big deal.","zh-TW":"這沒什麼大不了的。"},{"en":"This is a big decision.","zh-TW":"這是一個重大決定。"}]', NULL, NULL, 1, 650, NULL),
(651, 'big data', '/bɪɡ ˈdeɪtə/', 'noun', '{"zh-TW":["大數據"],"en":["extremely large datasets analyzed to reveal patterns and trends"]}', NULL, 'big data analytics / leverage big data', '[{"en":"Big data analytics helps businesses make better decisions.","zh-TW":"大數據分析幫助企業做出更好的決策。"},{"en":"The company invested in big data infrastructure.","zh-TW":"公司投資了大數據基礎設施。"}]', NULL, NULL, 3, 651, NULL),
(652, 'bilateral', '/baɪˈlætərəl/', 'adjective', '{"zh-TW":["雙邊的"],"en":["involving two parties, especially countries"]}', '{"prefix":{"text":"bi-","meaning":"two (二)"},"root":{"text":"later","meaning":"side (邊)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"與兩邊有關的，即「雙邊的」。"}', 'bilateral agreement/trade/relations', '[{"en":"The two countries signed a bilateral trade agreement.","zh-TW":"兩國簽署了雙邊貿易協定。"},{"en":"Bilateral relations have improved significantly.","zh-TW":"雙邊關係已顯著改善。"}]', NULL, NULL, 3, 652, 959),
(653, 'bilateral agreement', '/ˌbaɪˈlætərəl əˈɡriːmənt/', 'noun', '{"zh-TW":["雙邊協議"],"en":["an agreement entered into by two parties, typically between two governments or organizations"]}', NULL, 'sign a bilateral agreement / bilateral trade agreement', '[{"en":"The two countries signed a bilateral agreement to reduce tariffs.","zh-TW":"兩國簽署了一項雙邊協議以降低關稅。"},{"en":"A bilateral agreement on data sharing was reached after months of talks.","zh-TW":"經過數月談判，達成了一項數據共享的雙邊協議。"}]', '{"opposite":"multilateral agreement"}', NULL, 5, 653, NULL),
(654, 'bilingual', '/''baɪˈlɪŋɡwəl/', 'adjective', '{"zh-TW":["雙語的；使用兩種語言的"],"en":["able to speak two languages fluently; relating to or expressed in two languages"]}', NULL, 'bilingual education / bilingual employee / fully bilingual', '[{"en":"The company prefers bilingual candidates who can communicate in both English and Mandarin.","zh-TW":"公司偏好能用英語和普通話溝通的雙語候選人。"},{"en":"Growing up in a bilingual household gave her a natural advantage in language learning.","zh-TW":"在雙語家庭中長大給了她語言學習的天然優勢。"}]', '{"noun":"bilingualism"}', NULL, 3, 654, NULL),
(655, 'bill', '/bɪl/', 'noun', '{"zh-TW":["帳單；費用"],"en":["a list of charges to be paid"]}', NULL, 'pay the bill / split the bill', '[{"en":"We asked the waiter for the bill after dessert.","zh-TW":"吃完甜點後我們要求服務生結帳。"},{"en":"Let''s split the bill equally among the four of us.","zh-TW":"讓我們四個人平分帳單。"}]', '{"verb":"bill","adjective":"billed"}', NULL, 1, 655, NULL),
(656, 'bill of exchange', '/bɪl əv ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["匯票"],"en":["a written order from one party to another to pay a specified amount at a set time"]}', NULL, 'draw a bill of exchange / accept a bill of exchange', '[{"en":"The exporter drew a bill of exchange on the importer for payment.","zh-TW":"出口商向進口商開立了匯票以獲取付款。"},{"en":"A bill of exchange is commonly used in international trade finance.","zh-TW":"匯票在國際貿易融資中廣泛使用。"}]', NULL, NULL, 5, 656, NULL),
(657, 'bill of lading', '/bɪl əv ˈleɪdɪŋ/', 'noun', '{"zh-TW":["提單"],"en":["a document acknowledging receipt of cargo for shipment"]}', NULL, 'issue a bill of lading / original bill of lading', '[{"en":"The shipper provided a bill of lading for the cargo.","zh-TW":"發貨人為貨物提供了提單。"},{"en":"A clean bill of lading indicates the goods arrived undamaged.","zh-TW":"清潔提單表明貨物完好無損地到達。"}]', NULL, NULL, 5, 657, NULL),
(658, 'billing cycle', '/ˈbɪlɪŋ ˈsaɪkəl/', 'noun', '{"zh-TW":["計費週期；帳單週期"],"en":["the recurring period between bills sent to a customer"]}', NULL, 'monthly billing cycle / end of billing cycle', '[{"en":"The billing cycle is 30 days from the date of service.","zh-TW":"計費週期為服務日期起30天。"},{"en":"Your statement arrives at the end of each billing cycle.","zh-TW":"您的帳單在每個計費週期結束時到達。"}]', NULL, NULL, 5, 658, NULL),
(659, 'billing rate', '/ˈbɪlɪŋ reɪt/', 'noun', '{"zh-TW":["計費率；收費率"],"en":["the rate at which a professional service charges clients for time or work"]}', NULL, 'set the billing rate / billing rate per hour', '[{"en":"The consulting firm''s billing rate is $250 per hour.","zh-TW":"諮詢公司的計費率為每小時250元。"},{"en":"Billing rates vary depending on the seniority of the assigned consultant.","zh-TW":"計費率因指派顧問的資歷不同而有所不同。"}]', NULL, NULL, 4, 659, NULL),
(660, 'billion', 'ˈbɪljən', 'noun', '{"zh-TW":["十億","龐大數量"],"en":["a thousand million","an extremely large number"]}', NULL, 'one billion/billion-dollar', '[{"en":"The company is now worth one billion dollars.","zh-TW":"公司現在價值十億美元。"}]', '{"adjective":"billion-dollar"}', NULL, 3, 660, NULL),
(661, 'binary classification', '/ˈbaɪnəri ˌklæsɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["二元分類"],"en":["a type of classification task involving two possible output categories"]}', NULL, 'binary classification model / binary classification problem / binary classification accuracy', '[{"en":"Email spam detection is a classic binary classification problem.","zh-TW":"電子郵件垃圾郵件檢測是一個經典的二元分類問題。"},{"en":"The model was trained to perform binary classification of medical images.","zh-TW":"該模型被訓練用於對醫學影像進行二元分類。"}]', NULL, NULL, 5, 661, NULL),
(662, 'binary tree', '/ˈbaɪnəri triː/', 'noun', '{"zh-TW":["二元樹"],"en":["a tree data structure where each node has at most two child nodes"]}', NULL, 'implement a binary tree / traverse a binary tree / balance a binary tree', '[{"en":"A binary search tree allows efficient data retrieval operations.","zh-TW":"二元搜索樹允許高效的數據檢索操作。"},{"en":"Binary trees are fundamental data structures taught in computer science.","zh-TW":"二元樹是計算機科學中教授的基本數據結構。"}]', NULL, NULL, 4, 662, NULL),
(663, 'bind', '/baɪnd/', 'verb', '{"zh-TW":["綁定；約束"],"en":["to tie or fasten tightly","to impose a legal obligation"]}', '{"root":{"text":"bind","meaning":"tie (綁)"},"logic":"源自古英語 bindan（綁住）。"}', 'legally binding / bind together', '[{"en":"The contract is legally binding.","zh-TW":"這份合約具有法律約束力。"},{"en":"The agreement binds both parties.","zh-TW":"協議對雙方都有約束力。"}]', '{"noun":"binding","adjective":"binding"}', NULL, 1, 663, NULL),
(664, 'binding', 'ˈbaɪndɪŋ', 'adjective', '{"zh-TW":["具有約束力的；有效的","必須遵守的"],"en":["legally enforceable","obligatory"]}', NULL, 'legally binding/binding agreement', '[{"en":"This is a legally binding contract.","zh-TW":"這是一份具有法律約束力的合約。"}]', '{"verb":"bind","noun":"binding"}', NULL, 3, 664, 515),
(665, 'binding agreement', '/ˈbaɪndɪŋ əˈɡriːmənt/', 'noun', '{"zh-TW":["具有法律約束力的協議"],"en":["a contract that is legally enforceable"]}', NULL, 'enter into a binding agreement / sign a binding agreement', '[{"en":"By signing, you enter into a legally binding agreement.","zh-TW":"簽署後，您進入具有法律約束力的協議。"},{"en":"The binding agreement outlines both parties'' responsibilities.","zh-TW":"具有法律約束力的協議概述了雙方的責任。"}]', NULL, NULL, 5, 665, NULL),
(666, 'binding contract', '/ˈbaɪndɪŋ ˈkɒntrækt/', 'noun', '{"zh-TW":["具有約束力的合約"],"en":["a legally enforceable agreement between two or more parties"]}', NULL, 'enter a binding contract / binding contract terms', '[{"en":"Both parties signed a binding contract specifying delivery deadlines.","zh-TW":"雙方簽署了一份規定交貨截止日期的具有約束力的合約。"},{"en":"A binding contract requires consideration, capacity, and mutual consent.","zh-TW":"具有約束力的合約需要代價、能力和雙方同意。"}]', '{"adjective":"binding"}', NULL, 5, 666, NULL),
(667, 'bioavailability', '/ˌbaɪəʊəˌveɪləˈbɪlɪti/', 'noun', '{"zh-TW":["生物利用度；生物可用性"],"en":["the proportion of a drug that enters circulation and has an active effect"]}', NULL, 'improve bioavailability / oral bioavailability / assess bioavailability', '[{"en":"The new formulation increased the bioavailability of the active compound.","zh-TW":"新製劑提高了活性化合物的生物利用度。"},{"en":"Bioavailability determines how much of a drug reaches its target.","zh-TW":"生物利用度決定了多少藥物到達其靶標。"}]', '{"adjective":"bioavailable"}', NULL, 5, 667, NULL),
(668, 'biodegradable', '/ˌbaɪəʊdɪˈɡreɪdəbəl/', 'adjective', '{"zh-TW":["可生物降解的"],"en":["capable of being decomposed naturally by living organisms"]}', NULL, 'biodegradable packaging / biodegradable material', '[{"en":"The company replaced plastic with biodegradable packaging.","zh-TW":"公司將塑膠替換為可生物降解包裝。"},{"en":"Biodegradable products reduce environmental pollution.","zh-TW":"可生物降解產品減少了環境污染。"}]', '{"noun":"biodegradation","verb":"biodegrade"}', NULL, 5, 668, NULL),
(669, 'biodiversity', '/ˌbaɪəʊdaɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["生物多樣性"],"en":["the variety of plant and animal life in an ecosystem"]}', NULL, 'protect biodiversity / loss of biodiversity', '[{"en":"Deforestation threatens biodiversity in tropical regions.","zh-TW":"森林砍伐威脅熱帶地區的生物多樣性。"},{"en":"Conservation efforts aim to preserve biodiversity.","zh-TW":"保育工作旨在保護生物多樣性。"}]', '{"adjective":"biodiverse"}', NULL, 4, 669, NULL),
(670, 'biodiversity loss', '/''baɪəʊdaɪˌvɜːrsɪti lɒs/', 'noun', '{"zh-TW":["生物多樣性喪失"],"en":["the decline in the number and variety of species in an ecosystem, often due to human activity"]}', NULL, 'combat biodiversity loss / cause of biodiversity loss / biodiversity loss crisis', '[{"en":"Scientists warn that biodiversity loss threatens the stability of ecosystems worldwide.","zh-TW":"科學家警告，生物多樣性喪失威脅到全球生態系統的穩定性。"},{"en":"Deforestation is one of the primary drivers of biodiversity loss in tropical regions.","zh-TW":"森林砍伐是熱帶地區生物多樣性喪失的主要驅動因素之一。"}]', '{"noun":"biodiversity"}', NULL, 5, 670, NULL),
(671, 'biomass', '/ˈbaɪəʊmæs/', 'noun', '{"zh-TW":["生物質；生物量"],"en":["organic material from plants and animals used as a renewable energy source"]}', NULL, 'biomass energy / biomass fuel / biomass power plant', '[{"en":"Biomass energy is generated by burning organic materials such as wood and crop waste.","zh-TW":"生物質能源是通過燃燒木材和農作物廢料等有機材料產生的。"},{"en":"A new biomass power plant will provide clean electricity to 50,000 homes.","zh-TW":"一座新的生物質發電廠將為五萬戶家庭提供清潔電力。"}]', '{"adjective":"biomass-based"}', NULL, 3, 671, NULL),
(672, 'biometric', '/ˌbaɪəˈmetrɪk/', 'adjective', '{"zh-TW":["生物辨識的"],"en":["relating to unique physical or behavioral characteristics used for identification"]}', NULL, 'biometric authentication / biometric data / biometric scanner', '[{"en":"Biometric authentication uses fingerprints or facial recognition to verify identity.","zh-TW":"生物辨識認證使用指紋或臉部識別來驗證身份。"},{"en":"Mobile phones increasingly use biometric unlocking for security.","zh-TW":"行動電話越來越多地使用生物辨識解鎖以確保安全。"}]', '{"noun":"biometrics"}', NULL, 3, 672, NULL),
(673, 'biomimicry', '/ˌbaɪəʊˈmɪmɪkri/', 'noun', '{"zh-TW":["仿生學"],"en":["the design of products inspired by natural systems and biological processes"]}', NULL, 'apply biomimicry / biomimicry design / biomimicry principles', '[{"en":"Biomimicry draws on nature''s solutions to create sustainable technologies.","zh-TW":"仿生學借鑒自然的解決方案來創造可持續技術。"},{"en":"Velcro was invented through biomimicry inspired by burr seeds.","zh-TW":"魔鬼氈是通過受芒刺種子啟發的仿生學發明的。"}]', '{"adjective":"biomimetic"}', NULL, 4, 673, NULL),
(674, 'biopsy', '/ˈbaɪɒpsi/', 'noun', '{"zh-TW":["活組織切片檢查；活檢"],"en":["a medical procedure examining a tissue sample to diagnose disease"]}', NULL, 'perform a biopsy / tissue biopsy / biopsy result', '[{"en":"The biopsy revealed the presence of cancerous cells.","zh-TW":"活檢顯示存在癌細胞。"},{"en":"A biopsy is the definitive test for confirming cancer diagnoses.","zh-TW":"活檢是確認癌症診斷的決定性測試。"}]', '{"verb":"biopsy"}', NULL, 2, 674, NULL),
(675, 'biosphere', '/ˈbaɪəsfɪər/', 'noun', '{"zh-TW":["生物圈"],"en":["the regions of the surface of the earth occupied by living organisms"]}', NULL, 'preserve the biosphere / biosphere reserve / biosphere sustainability', '[{"en":"Human activity is altering the biosphere at an unprecedented rate.","zh-TW":"人類活動正在以前所未有的速度改變生物圈。"},{"en":"Maintaining biosphere integrity is essential for life on Earth.","zh-TW":"維護生物圈完整性對地球生命至關重要。"}]', '{"adjective":"biospheric"}', NULL, 3, 675, NULL),
(676, 'biotechnology', '/ˌbaɪəʊtekˈnɒlədʒi/', 'noun', '{"zh-TW":["生物技術"],"en":["the use of biological systems and organisms in technology and industry"]}', NULL, 'apply biotechnology / biotechnology research / biotechnology company', '[{"en":"Biotechnology has revolutionized drug development and agricultural yields.","zh-TW":"生物技術革命性地改變了藥物開發和農業產量。"},{"en":"CRISPR gene editing is a breakthrough biotechnology with wide applications.","zh-TW":"CRISPR基因編輯是一項具有廣泛應用的突破性生物技術。"}]', '{"adjective":"biotechnological","adverb":"biotechnologically"}', NULL, 5, 676, NULL),
(677, 'bipartisan', '/ˌbaɪˈpɑːrtɪzən/', 'adjective', '{"zh-TW":["兩黨的；跨黨派的"],"en":["supported by or consisting of members from two political parties"]}', NULL, 'bipartisan support / bipartisan agreement / bipartisan effort', '[{"en":"The infrastructure bill received rare bipartisan support in Congress.","zh-TW":"基礎設施法案在國會獲得了罕見的兩黨支持。"},{"en":"Bipartisan cooperation is needed to address long-term fiscal challenges.","zh-TW":"需要跨黨派合作來解決長期財政挑戰。"}]', '{"noun":"bipartisanship"}', NULL, 4, 677, NULL),
