(682, 'bitter', '/ˈbɪtər/', 'adjective', '{"zh-TW":["苦的；痛苦的"],"en":["having a sharp unpleasant taste"]}', NULL, 'bitter cold / bitter experience', '[{"en":"This coffee tastes bitter.","zh-TW":"這咖啡嘗起來很苦。"},{"en":"It was a bitter experience.","zh-TW":"那是一段痛苦的經歷。"}]', '{"noun":"bitterness","adverb":"bitterly"}', NULL, 2, 682, NULL),
(683, 'black', '/blæk/', 'adjective', '{"zh-TW":["黑色的","黑色的；黑暗的"],"en":["the darkest color","having the darkest color; very dark"]}', NULL, 'black and white / black market; black and white / in the black (有盈餘)', '[{"en":"She was wearing a black dress.","zh-TW":"她穿著一件黑色洋裝。"},{"en":"It''s not a black and white issue.","zh-TW":"這不是一個非黑即白的問題。"},{"en":"The company is finally in the black.","zh-TW":"公司終於有盈餘了。"}]', NULL, NULL, 2, 683, NULL),
