(685, 'blanch', '/''blɑːntʃ/', 'verb', '{"zh-TW":["汆燙；焯水"],"en":["to briefly cook vegetables in boiling water and then cool them in ice water to preserve color and texture"]}', NULL, 'blanch the vegetables / blanch for two minutes / briefly blanch', '[{"en":"Blanch the green beans for two minutes to preserve their bright color.","zh-TW":"汆燙青豆兩分鐘以保持其鮮亮的顏色。"},{"en":"She blanched the tomatoes to make it easier to peel their skins.","zh-TW":"她汆燙番茄，使其更容易去皮。"}]', NULL, NULL, 2, 685, NULL),
