(687, 'blended learning', '/''blendɪd ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["混成學習；混合式學習"],"en":["an approach combining traditional face-to-face teaching with online instruction"]}', NULL, 'implement blended learning / blended learning model / benefits of blended learning', '[{"en":"Blended learning gives students flexibility to study at their own pace online.","zh-TW":"混成學習讓學生可以靈活地按自己的節奏在線學習。"},{"en":"The university shifted to a blended learning model during the pandemic.","zh-TW":"大學在疫情期間轉向了混成學習模式。"}]', NULL, NULL, 5, 687, NULL),
