(689, 'blind', '/blaɪnd/', 'adjective', '{"zh-TW":["瞎的；盲目的"],"en":["unable to see"]}', NULL, 'turn a blind eye / blind spot', '[{"en":"He has been blind since birth.","zh-TW":"他生下來就看不見。"},{"en":"Don''t turn a blind eye to injustice.","zh-TW":"不要對不公正視而不見。"}]', '{"noun":"blindness","adverb":"blindly"}', NULL, 2, 689, NULL),
(690, 'blizzard', '/ˈblɪzərd/', 'noun', '{"zh-TW":["暴風雪"],"en":["a severe snowstorm with strong winds"]}', '{"root":{"text":"blizzard","meaning":"violent blow (猛烈吹襲)"},"logic":"指伴隨強風的猛烈暴風雪。"}', 'caught in a blizzard / blizzard conditions', '[{"en":"The blizzard shut down all major highways.","zh-TW":"暴風雪導致所有主要公路關閉。"},{"en":"Schools were closed due to the blizzard.","zh-TW":"學校因暴風雪停課。"}]', NULL, NULL, 3, 690, NULL),
(691, 'block', '/blɒk/', 'noun', '{"zh-TW":["街區；障礙物"],"en":["a solid piece; an area of buildings"]}', NULL, 'road block / around the block', '[{"en":"The office is two blocks away.","zh-TW":"辦公室在兩個街區外。"},{"en":"A tree blocked the road.","zh-TW":"一棵樹擋住了路。"}]', '{"verb":"block"}', NULL, 2, 691, NULL),
