(694, 'blood', '/blʌd/', 'noun', '{"zh-TW":["血液","血；血液","血液；血統"],"en":["the red liquid flowing through the body","the red liquid in your body","the red liquid that flows through the body"]}', NULL, 'blood pressure / blood test; blood pressure / blood test / in cold blood', '[{"en":"High blood pressure is a common issue.","zh-TW":"高血壓是常見的問題。"},{"en":"The doctor ordered a blood test.","zh-TW":"醫生安排了驗血。"},{"en":"She donated blood today.","zh-TW":"她今天捐了血。"},{"en":"High blood pressure is dangerous.","zh-TW":"高血壓是危險的。"},{"en":"He donated blood at the hospital.","zh-TW":"他在醫院捐血。"},{"en":"High blood pressure is a common condition.","zh-TW":"高血壓是常見的疾病。"}]', '{"noun":"blood","adjective":"bloody","verb":"bleed"}', NULL, 2, 694, NULL),
(695, 'blood bank', '/blʌd bæŋk/', 'noun', '{"zh-TW":["血庫"],"en":["a store of blood for use in medical treatment"]}', NULL, 'donate to a blood bank / blood bank supply', '[{"en":"Donate blood to help replenish the blood bank.","zh-TW":"捐血以幫助補充血庫存量。"},{"en":"The blood bank maintained adequate supplies for emergencies.","zh-TW":"血庫維持了足夠的緊急備用存量。"}]', NULL, NULL, 4, 695, NULL),
(696, 'blood pressure', '/blʌd ˈprɛʃər/', 'noun', '{"zh-TW":["血壓"],"en":["the pressure of blood circulating against vessel walls"]}', NULL, 'high blood pressure / check blood pressure', '[{"en":"The nurse checked his blood pressure every hour.","zh-TW":"護士每小時檢查他的血壓。"},{"en":"High blood pressure increases the risk of heart disease.","zh-TW":"高血壓增加了心臟病的風險。"}]', NULL, NULL, 5, 696, NULL),
(697, 'blood test', '/blʌd tɛst/', 'noun', '{"zh-TW":["血液檢查"],"en":["an examination of a blood sample for diagnosis"]}', NULL, 'take a blood test / blood test results', '[{"en":"The doctor ordered a blood test to check cholesterol.","zh-TW":"醫生要求進行血液檢查以檢測膽固醇。"},{"en":"Your blood test results will be ready in two days.","zh-TW":"您的血液檢查結果兩天後即可查看。"}]', NULL, NULL, 4, 697, NULL),
(698, 'blood type', '/blʌd taɪp/', 'noun', '{"zh-TW":["血型"],"en":["a classification of blood based on antigens"]}', NULL, 'blood type O / know your blood type', '[{"en":"It is important to know your blood type in case of emergency.","zh-TW":"在緊急情況下知道自己的血型非常重要。"},{"en":"The doctor asked about her blood type before surgery.","zh-TW":"醫生在手術前詢問了她的血型。"}]', NULL, NULL, 4, 698, NULL),
